
'use client';

import { useRef, useState, useEffect, FormEvent } from 'react';

type Message = {
    id: number;
    role: 'user' | 'assistant';
    content: string;
};

type UploadedFile = {
    id: number;
    name: string;
    status: string;
};

const API_URL =
    process.env.NEXT_PUBLIC_API_URL || 'http://localhost:3000';

const suggestions = [
    {
        icon: '⌕',
        title: 'Explain my documents',
        description: 'Understand difficult concepts in your PDFs',
        prompt: 'Explain the main concepts in my uploaded documents.',
    },
    {
        icon: '✦',
        title: 'Create a study plan',
        description: 'Organize my upcoming study sessions',
        prompt: 'Help me create a study plan for my upcoming exams.',
    },
    {
        icon: '▤',
        title: 'Summarize a topic',
        description: 'Get a clear and simple summary',
        prompt: 'Summarize the main topics in my uploaded documents.',
    },
];

export default function Home() {
    const [messages, setMessages] = useState<Message[]>([]);
    const [input, setInput] = useState('');
    const [files, setFiles] = useState<UploadedFile[]>([]);
    const [loading, setLoading] = useState(false);
    const [uploading, setUploading] = useState(false);
    const [error, setError] = useState('');

    const fileInputRef = useRef<HTMLInputElement>(null);
    const chatEndRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }, [messages, loading]);

    async function sendMessage(
        event?: FormEvent,
        customMessage?: string,
    ) {
        event?.preventDefault();

        const message = (customMessage ?? input).trim();

        if (!message || loading) return;

        setError('');
        setInput('');

        setMessages((previous) => [
            ...previous,
            {
                id: Date.now(),
                role: 'user',
                content: message,
            },
        ]);

        setLoading(true);

        try {
            const response = await fetch(`${API_URL}/ai/chat`, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({ message }),
            });

            if (!response.ok) {
                throw new Error('Unable to get a response from StudyMate.');
            }

            const data = await response.json();

            setMessages((previous) => [
                ...previous,
                {
                    id: Date.now() + 1,
                    role: 'assistant',
                    content: data.answer || 'I could not generate an answer.',
                },
            ]);
        } catch (err) {
            setError(
                err instanceof Error
                    ? err.message
                    : 'Something went wrong.',
            );
        } finally {
            setLoading(false);
        }
    }

    async function uploadFile(
        event: React.ChangeEvent<HTMLInputElement>,
    ) {
        const file = event.target.files?.[0];

        if (!file) return;

        if (file.type !== 'application/pdf') {
            setError('Please select a PDF file.');
            event.target.value = '';
            return;
        }

        setError('');
        setUploading(true);

        const formData = new FormData();
        formData.append('file', file);

        try {
            const response = await fetch(
                `${API_URL}/documents/upload`,
                {
                    method: 'POST',
                    body: formData,
                },
            );

            if (!response.ok) {
                throw new Error('File upload failed.');
            }

            const data = await response.json();

            setFiles((previous) => [
                ...previous,
                {
                    id: Date.now(),
                    name: file.name,
                    status: 'Uploaded',
                },
            ]);

            setMessages((previous) => [
                ...previous,
                {
                    id: Date.now() + 1,
                    role: 'assistant',
                    content:
                        data.message ||
                        `Your file "${file.name}" was uploaded successfully. You can now ask me questions about it.`,
                },
            ]);
        } catch (err) {
            setError(
                err instanceof Error
                    ? err.message
                    : 'Upload failed.',
            );
        } finally {
            setUploading(false);

            if (fileInputRef.current) {
                fileInputRef.current.value = '';
            }
        }
    }

    function startNewChat() {
        setMessages([]);
        setInput('');
        setError('');
    }

    return (
        <main className="app-shell">

            {/* Sidebar */}
            <aside className="sidebar">

                <div className="brand">
                    <div className="brand-icon">✦</div>
                    <span>StudyMate<span className="brand-ai"> AI</span></span>
                </div>

                <button className="new-chat-btn" onClick={startNewChat}>
                    <span>＋</span> New conversation
                </button>

                <div className="sidebar-section">
                    <p className="section-label">WORKSPACE</p>

                    <button className="nav-item active">
                        <span>◈</span> AI Assistant
                    </button>

                    <button
                        className="nav-item"
                        onClick={() => fileInputRef.current?.click()}
                    >
                        <span>▤</span> My Documents
                    </button>

                    <button className="nav-item">
                        <span>✓</span> Study Tasks
                    </button>
                </div>

                <div className="sidebar-section documents-section">
                    <p className="section-label">YOUR DOCUMENTS</p>

                    {files.length === 0 ? (
                        <p className="empty-files">
                            Your uploaded files will appear here.
                        </p>
                    ) : (
                        files.map((file) => (
                            <div className="document-item" key={file.id}>
                                <span className="pdf-icon">PDF</span>
                                <span className="document-name">{file.name}</span>
                            </div>
                        ))
                    )}

                    <button
                        className="upload-sidebar-btn"
                        onClick={() => fileInputRef.current?.click()}
                    >
                        ＋ Upload document
                    </button>
                </div>

                <div className="sidebar-bottom">
                    <div className="profile-avatar">S</div>
                    <div>
                        <p className="profile-name">StudyMate User</p>
                        <p className="profile-plan">Personal workspace</p>
                    </div>
                    <span className="profile-menu">···</span>
                </div>

            </aside>

            {/* Main Content */}
            <section className="main-content">

                <header className="topbar">
                    <div>
                        <span className="breadcrumb">Workspace</span>
                        <span className="breadcrumb-divider">/</span>
                        <span className="breadcrumb-current">AI Assistant</span>
                    </div>

                    <div className="topbar-right">
                        <span className="online-dot" />
                        <span className="online-label">AI is ready</span>
                        <div className="topbar-avatar">S</div>
                    </div>
                </header>

                <div className="chat-container">

                    <div className="chat-content">

                        {messages.length === 0 ? (
                            <div className="welcome-screen">

                                <div className="welcome-icon">✦</div>

                                <p className="welcome-eyebrow">
                                    YOUR PERSONAL AI STUDY PARTNER
                                </p>

                                <h1>
                                    Learn smarter.
                                    <br />
                                    <span>Achieve more.</span>
                                </h1>

                                <p className="welcome-description">
                                    Upload your study materials, ask questions,
                                    create study plans, and let AI help you stay
                                    ahead of your learning goals.
                                </p>

                                <div className="suggestion-grid">
                                    {suggestions.map((item) => (
                                        <button
                                            className="suggestion-card"
                                            key={item.title}
                                            onClick={() => sendMessage(undefined, item.prompt)}
                                        >
                      <span className="suggestion-icon">
                        {item.icon}
                      </span>

                                            <span className="suggestion-title">
                        {item.title}
                      </span>

                                            <span className="suggestion-description">
                        {item.description}
                      </span>

                                            <span className="suggestion-arrow">↗</span>
                                        </button>
                                    ))}
                                </div>

                                <button
                                    className="upload-main-btn"
                                    onClick={() => fileInputRef.current?.click()}
                                >
                                    <span>＋</span>
                                    Upload your first PDF
                                </button>

                            </div>
                        ) : (
                            <div className="messages-list">
                                {messages.map((message) => (
                                    <div
                                        className={`message-row ${message.role}`}
                                        key={message.id}
                                    >
                                        {message.role === 'assistant' && (
                                            <div className="message-avatar">✦</div>
                                        )}

                                        <div className="message-bubble">
                                            <p className="message-role">
                                                {message.role === 'assistant'
                                                    ? 'StudyMate AI'
                                                    : 'You'}
                                            </p>

                                            <div className="message-text">
                                                {message.content}
                                            </div>
                                        </div>

                                        {message.role === 'user' && (
                                            <div className="user-message-avatar">S</div>
                                        )}
                                    </div>
                                ))}

                                {loading && (
                                    <div className="message-row assistant">
                                        <div className="message-avatar">✦</div>
                                        <div className="typing-indicator">
                                            <span />
                                            <span />
                                            <span />
                                            <small>StudyMate is thinking...</small>
                                        </div>
                                    </div>
                                )}

                                <div ref={chatEndRef} />
                            </div>
                        )}

                    </div>

                    {/* Input Area */}
                    <div className="chat-footer">

                        {error && (
                            <div className="error-message">
                                {error}
                            </div>
                        )}

                        <form
                            className="chat-input-box"
                            onSubmit={(event) => sendMessage(event)}
                        >
              <textarea
                  value={input}
                  onChange={(event) => setInput(event.target.value)}
                  placeholder="Ask anything about your studies..."
                  rows={1}
                  onKeyDown={(event) => {
                      if (
                          event.key === 'Enter' &&
                          !event.shiftKey
                      ) {
                          event.preventDefault();
                          sendMessage();
                      }
                  }}
              />

                            <div className="input-actions">
                                <div className="input-left-actions">
                                    <button
                                        type="button"
                                        className="attach-btn"
                                        title="Upload PDF"
                                        onClick={() => fileInputRef.current?.click()}
                                    >
                                        ＋
                                    </button>

                                    <span className="input-hint">
                    Attach a PDF or ask a question
                  </span>
                                </div>

                                <button
                                    type="submit"
                                    className="send-btn"
                                    disabled={!input.trim() || loading}
                                >
                                    ↑
                                </button>
                            </div>
                        </form>

                        <p className="disclaimer">
                            StudyMate AI can make mistakes. Verify important information.
                        </p>

                    </div>

                </div>

            </section>

            {/* Hidden PDF Input */}
            <input
                ref={fileInputRef}
                type="file"
                accept="application/pdf,.pdf"
                hidden
                onChange={uploadFile}
            />

            {uploading && (
                <div className="upload-status">
                    <span className="loader" />
                    Uploading your document...
                </div>
            )}

        </main>
    );
}
